@jax.jit
def inner(x):
    return jnp.tanh(x) * 2.0

def misc(x):
    y = inner(x)
    y = jax.nn.relu(y)                     # relu is a custom_jvp function
    jax.debug.print("y0 = {}", y[0])
    return jax.lax.stop_gradient(y) + jax.checkpoint(lambda v: jnp.sin(v) * v)(x)
